/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: renderCard
 *   Constants: controls, item
 * Tests
 *   - an automatically muted preview offers an honest sound action rather than claiming sound is on
 *   - a hover-to-stream transition waits for actual playback while mute toggles preserve readiness
 *   - enabling sound on an already ready stream does not return the card to a loading label
 *   - uses real metadata and independent non-nested playback, preview, save and framing controls
 *   - pauses the playing MediaTrack without relaunching it or changing its metadata
 *   - the preview control represents sound state and forwards mute changes without stopping the preview
 *   - room-owned playback disables preview sound without issuing a shared room pause
 *   - frame options change only presentation and restore focus after selection and Escape
 *   - signed-out Save remains actionable and explains authentication without launching playback
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { fireEvent, render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useEffect } from 'react';

import type { AudioTrackSummary } from '../../api/contentSchemas';
import { VideoPreviewCard } from './VideoPreviewCard';

const controls = vi.hoisted(() => ({ playingId: null as string | null, roomActive: false, active: false,
  intent: 'hover' as 'hover' | 'explicit', previewSource: 'clip', muted: true, reportedMuted: null as boolean | null,
  reportMuted: vi.fn(), pause: vi.fn(), toggle: vi.fn(), stop: vi.fn() }));
vi.mock('../../player', () => ({ playerStore: { pause: controls.pause, subscribe: () => () => undefined,
  isRoomPlaybackActive: () => controls.roomActive }, usePlayingTrackId: () => controls.playingId }));
vi.mock('./useVideoCardPreview', () => ({ useVideoCardPreview: () => ({
  active: controls.active, intent: controls.intent, muted: controls.muted,
  actualMuted: controls.reportedMuted ?? controls.muted, reportMuted: controls.reportMuted,
  cardRef: () => undefined, stop: controls.stop, toggle: controls.toggle
}) }));
vi.mock('../../components/CardVideoPreview', () => ({ default: ({ muted, intent, onReady, onLoading }: {
  muted: boolean; intent: string; onReady: () => void; onLoading: () => void
}) => {
  useEffect(onLoading, [controls.previewSource, onLoading]);
  return <span data-testid="preview-media" data-muted={muted} data-intent={intent} onClick={onReady} />;
} }));

const item: AudioTrackSummary = {
  contentType: 'audioTrack', id: 'real-video', title: 'A Window onto the River', artworkUrl: '',
  artistNames: ['Legacy Artist'], displayByline: 'Documented Performer', albumId: null,
  albumTitle: 'Along the Way', duration: '0:22', mediaType: 'video', streamUrl: '/content/mediaTrack/stream/real-video'
};

/** Uses the real Save control while keeping playback and preview ownership observable. */
const renderCard = (track = item) => {
  const onPlay = vi.fn();
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  return { onPlay, client, ...render(<QueryClientProvider client={client}>
    <VideoPreviewCard item={track} onPlay={onPlay} saved={false} />
  </QueryClientProvider>) };
};

beforeEach(() => {
  controls.playingId = null; controls.roomActive = false; controls.active = false;
  controls.intent = 'hover'; controls.previewSource = 'clip'; controls.muted = true; controls.reportedMuted = null; vi.clearAllMocks();
});

test('an automatically muted preview offers an honest sound action rather than claiming sound is on', async () => {
  controls.active = true; controls.muted = false; controls.reportedMuted = true;
  renderCard();
  fireEvent.click(await screen.findByTestId('preview-media'));
  const button = screen.getByRole('button', { name: `Unmute preview for ${item.title}` });
  expect(button).toHaveAttribute('aria-pressed', 'false');
  expect(button).toHaveTextContent('Click for sound');
  expect(screen.queryByText('Sound on')).not.toBeInTheDocument();
});

test('a hover-to-stream transition waits for actual playback while mute toggles preserve readiness', async () => {
  controls.active = true;
  const { client, onPlay, rerender } = renderCard();
  fireEvent.click(await screen.findByTestId('preview-media'));
  const update = () => rerender(<QueryClientProvider client={client}>
    <VideoPreviewCard item={item} onPlay={onPlay} saved={false} />
  </QueryClientProvider>);

  controls.intent = 'explicit'; controls.muted = false; controls.previewSource = 'stream'; update();
  expect(screen.getByRole('button', { name: `Mute preview for ${item.title}` })).toHaveTextContent('Preview');
  fireEvent.click(screen.getByTestId('preview-media'));
  expect(screen.getByRole('button', { name: `Mute preview for ${item.title}` })).toHaveTextContent('Sound on');
  controls.muted = true; update();
  controls.muted = false; update();
  expect(screen.getByRole('button', { name: `Mute preview for ${item.title}` })).toHaveTextContent('Sound on');
});

test('enabling sound on an already ready stream does not return the card to a loading label', async () => {
  controls.active = true; controls.previewSource = 'stream';
  const { client, onPlay, rerender } = renderCard();
  fireEvent.click(await screen.findByTestId('preview-media'));
  controls.intent = 'explicit'; controls.muted = false;
  rerender(<QueryClientProvider client={client}>
    <VideoPreviewCard item={item} onPlay={onPlay} saved={false} />
  </QueryClientProvider>);
  expect(screen.getByRole('button', { name: `Mute preview for ${item.title}` })).toHaveTextContent('Sound on');
});

test('uses real metadata and independent non-nested playback, preview, save and framing controls', async () => {
  const user = userEvent.setup();
  const { container, onPlay } = renderCard();
  expect(screen.getByRole('heading', { name: item.title })).toBeInTheDocument();
  expect(screen.getByText('Documented Performer')).toBeInTheDocument();
  expect(screen.queryByText('Legacy Artist')).not.toBeInTheDocument();
  expect(container.querySelectorAll('button button')).toHaveLength(0);
  expect(container.querySelector('[data-video-frame="portrait"]')).toBeInTheDocument();

  await user.click(screen.getByRole('button', { name: `Unmute preview for ${item.title}` }));
  expect(controls.toggle).toHaveBeenCalledTimes(1);
  expect(onPlay).not.toHaveBeenCalled();
  await user.click(screen.getByRole('button', { name: `Play ${item.title} by Documented Performer` }));
  expect(controls.stop).toHaveBeenCalled();
  expect(onPlay).toHaveBeenCalledWith(item);
});

test('pauses the playing MediaTrack without relaunching it or changing its metadata', async () => {
  controls.playingId = item.id;
  const { onPlay } = renderCard();
  expect(screen.getByRole('button', { name: `Unmute preview for ${item.title}` })).toBeDisabled();
  await userEvent.setup().click(screen.getByRole('button', { name: `Pause ${item.title}` }));
  expect(controls.pause).toHaveBeenCalledTimes(1);
  expect(onPlay).not.toHaveBeenCalled();
});

test('the preview control represents sound state and forwards mute changes without stopping the preview', async () => {
  controls.active = true; controls.intent = 'explicit'; controls.muted = false;
  const { client, onPlay, rerender } = renderCard();
  expect(screen.getByRole('button', { name: `Mute preview for ${item.title}` })).toHaveAttribute('aria-pressed', 'true');
  expect(await screen.findByTestId('preview-media')).toHaveAttribute('data-muted', 'false');
  expect(screen.getByTestId('preview-media')).toHaveAttribute('data-intent', 'explicit');

  controls.muted = true;
  rerender(<QueryClientProvider client={client}><VideoPreviewCard item={item} onPlay={onPlay} saved={false} /></QueryClientProvider>);

  expect(screen.getByRole('button', { name: `Unmute preview for ${item.title}` })).toHaveAttribute('aria-pressed', 'false');
  expect(screen.getByTestId('preview-media')).toHaveAttribute('data-muted', 'true');
  expect(controls.stop).not.toHaveBeenCalled();
  expect(onPlay).not.toHaveBeenCalled();
});

test('room-owned playback disables preview sound without issuing a shared room pause', async () => {
  controls.roomActive = true;
  renderCard();
  const preview = screen.getByRole('button', { name: `Unmute preview for ${item.title}` });
  expect(preview).toBeDisabled();
  expect(preview.getAttribute('title')).toBeTruthy();
  await userEvent.setup().click(preview);
  expect(controls.toggle).not.toHaveBeenCalled();
  expect(controls.pause).not.toHaveBeenCalled();
});

test('frame options change only presentation and restore focus after selection and Escape', async () => {
  const user = userEvent.setup();
  const { container, onPlay } = renderCard();
  const more = screen.getByRole('button', { name: `${item.title} options` });
  await user.click(more);
  const dialog = await screen.findByRole('dialog', { name: `${item.title} options` });
  const slider = within(dialog).getByRole('slider', { name: `Frame position for ${item.title}` });
  slider.focus();
  fireEvent.change(slider, { target: { value: '100' } });
  expect(slider).toHaveValue('100');
  expect(container.querySelector('[data-video-frame]')).toHaveStyle({ '--video-position': '100%' });
  await user.keyboard('{Escape}');
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(more).toHaveFocus();

  await user.click(more);
  await user.click(await screen.findByRole('button', { name: 'Show full frame' }));
  expect(container.querySelector('[data-video-frame]')).toHaveStyle({ '--video-fit': 'contain' });
  expect(more).toHaveFocus();
  await user.click(more);
  expect(await screen.findByRole('slider')).toBeDisabled();
  await user.click(screen.getByRole('button', { name: 'Fill card' }));
  expect(container.querySelector('[data-video-frame]')).toHaveStyle({ '--video-fit': 'cover' });
  expect(onPlay).not.toHaveBeenCalled();
});

test('signed-out Save remains actionable and explains authentication without launching playback', async () => {
  const { onPlay } = renderCard();
  const save = await screen.findByRole('button', { name: 'Save to Library' });
  await userEvent.setup().click(save);
  expect(await screen.findByRole('alert')).toHaveTextContent(/log in/i);
  expect(onPlay).not.toHaveBeenCalled();
});
